  const canonical=captureCanonicalRankConfig233(env);
  if(canonical.present)return canonical.current()&&hasCanonicalMemberAccess233(env,roles);
  const eligible: string[] = env.ROLE_GUILD_MEMBER ? [env.ROLE_GUILD_MEMBER] : [];
